/* Admin Kullanıcı Özeti */

.auo-page {
  --auo-primary: #4557a3;
  --auo-primary-mid: #5b6fd6;
  --auo-surface: #ffffff;
  --auo-text: #0f172a;
  --auo-muted: #64748b;
  --auo-border: #e2e8f0;
  --auo-radius: 16px;
  --auo-shadow: 0 4px 24px rgba(69, 87, 163, 0.08);

  width: 100%;
  max-width: 100%;
  min-height: 100%;
  padding: 1.25rem 1rem 2.5rem;
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  color: var(--auo-text);
  background: linear-gradient(180deg, #f8fafc 0%, #eef2ff 100%);
  box-sizing: border-box;
}

.auo-page *,
.auo-page *::before,
.auo-page *::after {
  box-sizing: border-box;
}

.auo-page .auo__hero {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  margin-bottom: 1.25rem;
  padding: 1.35rem 1.5rem;
  border-radius: var(--auo-radius);
  background: linear-gradient(135deg, #4557a3 0%, #5b6fd6 55%, #7c8ce8 100%);
  color: #fff;
  box-shadow: 0 12px 40px rgba(69, 87, 163, 0.25);
}

.auo-page .auo__hero-main {
  min-width: 0;
}

.auo-page .auo__eyebrow {
  display: block;
  margin-bottom: 0.35rem;
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  opacity: 0.85;
}

.auo-page .auo__hero h1 {
  margin: 0 0 0.35rem;
  font-size: clamp(1.15rem, 2.4vw, 1.5rem);
  font-weight: 800;
  letter-spacing: -0.02em;
}

.auo-page .auo__hero p {
  margin: 0;
  font-size: 0.92rem;
  color: rgba(255, 255, 255, 0.92);
  line-height: 1.45;
}

.auo-page .auo__count {
  flex-shrink: 0;
  padding: 0.45rem 0.85rem;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.18);
  border: 1px solid rgba(255, 255, 255, 0.28);
  font-size: 0.82rem;
  font-weight: 700;
  white-space: nowrap;
}

.auo-page .auo__stats {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.85rem;
  margin-bottom: 1.25rem;
}

@media (min-width: 900px) {
  .auo-page .auo__stats {
    grid-template-columns: repeat(5, minmax(0, 1fr));
  }
}

.auo-page .auo-stat {
  display: flex;
  align-items: flex-start;
  gap: 0.75rem;
  padding: 1rem;
  background: var(--auo-surface);
  border: 1px solid var(--auo-border);
  border-radius: 14px;
  box-shadow: var(--auo-shadow);
  text-decoration: none;
  color: inherit;
  cursor: pointer;
  font: inherit;
  text-align: left;
  width: 100%;
  transition: border-color 0.15s ease, box-shadow 0.15s ease, transform 0.15s ease;
}

.auo-page a.auo-stat:hover,
.auo-page button.auo-stat:hover {
  border-color: #c7d2fe;
  box-shadow: 0 8px 22px rgba(69, 87, 163, 0.12);
  transform: translateY(-1px);
}

.auo-page a.auo-stat.is-active,
.auo-page button.auo-stat.is-active {
  border-color: var(--auo-primary);
  box-shadow: 0 0 0 3px rgba(69, 87, 163, 0.14);
}

.auo-page .auo-filter-clear {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  margin-left: auto;
  padding: 0.4rem 0.75rem;
  border: 1px solid var(--auo-border);
  border-radius: 999px;
  background: #fff;
  color: var(--auo-primary);
  font-size: 0.78rem;
  font-weight: 700;
  text-decoration: none;
  white-space: nowrap;
  font-family: inherit;
  cursor: pointer;
}

.auo-page .auo-filter-clear:hover {
  border-color: #c7d2fe;
  background: #eef2ff;
}

.auo-page .auo-stat__icon {
  flex-shrink: 0;
  width: 42px;
  height: 42px;
  display: grid;
  place-items: center;
  border-radius: 12px;
  background: rgba(69, 87, 163, 0.1);
  color: var(--auo-primary);
  font-size: 1.2rem;
}

.auo-page .auo-stat--today .auo-stat__icon {
  background: #ecfdf5;
  color: #047857;
}

.auo-page .auo-stat--pending .auo-stat__icon {
  background: #fff7ed;
  color: #c2410c;
}

.auo-page .auo-stat--messages .auo-stat__icon {
  background: #eff6ff;
  color: #1d4ed8;
}

.auo-page .auo-stat--muted .auo-stat__icon {
  background: #f1f5f9;
  color: #64748b;
}

.auo-page .auo-stat__label {
  display: block;
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--auo-muted);
  margin-bottom: 0.3rem;
  line-height: 1.3;
}

.auo-page .auo-stat__value {
  display: block;
  font-size: 1.55rem;
  font-weight: 800;
  line-height: 1;
  color: var(--auo-text);
}

.auo-page .auo__card {
  background: var(--auo-surface);
  border: 1px solid var(--auo-border);
  border-radius: var(--auo-radius);
  box-shadow: var(--auo-shadow);
  overflow: hidden;
}

.auo-page .auo__list-head {
  display: flex;
  align-items: flex-start;
  gap: 0.85rem;
  padding: 1.15rem 1.25rem;
  border-bottom: 1px solid var(--auo-border);
  background: #f8fafc;
}

.auo-page .auo__list-head--with-action {
  align-items: center;
}

.auo-page .auo__list-head-copy {
  flex: 1;
  min-width: 0;
}

.auo-page .auo-head-btn {
  flex-shrink: 0;
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  margin-left: auto;
  padding: 0.55rem 0.9rem;
  border-radius: 10px;
  border: 1px solid #c7d2fe;
  background: #eef2ff;
  color: #3730a3;
  font-size: 0.82rem;
  font-weight: 700;
  text-decoration: none;
  white-space: nowrap;
  transition: background 0.15s ease, border-color 0.15s ease;
}

.auo-page .auo-head-btn:hover {
  background: #e0e7ff;
  border-color: #a5b4fc;
  color: #312e81;
}

.auo-page .auo-head-btn .pi {
  font-size: 0.9rem;
}

.auo-page .auo-paginate {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 0.65rem;
  padding: 0.85rem 1.15rem;
  border-top: 1px solid var(--auo-border);
  background: #f8fafc;
}

.auo-page .auo-paginate__btn {
  width: 2.1rem;
  height: 2.1rem;
  border-radius: 8px;
  border: 1px solid #cbd5e1;
  background: #fff;
  color: #334155;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  text-decoration: none;
}

.auo-page a.auo-paginate__btn:hover {
  background: #eef2ff;
  border-color: #a5b4fc;
  color: #3730a3;
}

.auo-page .auo-paginate__btn:disabled,
.auo-page .auo-paginate__btn--disabled {
  opacity: 0.45;
  cursor: not-allowed;
  pointer-events: none;
}

.auo-page .auo-paginate__info {
  font-size: 0.84rem;
  font-weight: 700;
  color: #475569;
  min-width: 3.5rem;
  text-align: center;
}

@media (max-width: 720px) {
  .auo-page .auo__list-head--with-action {
    flex-wrap: wrap;
  }

  .auo-page .auo-head-btn {
    width: 100%;
    margin-left: 0;
    justify-content: center;
  }
}

.auo-page .auo__list-head-icon {
  flex-shrink: 0;
  width: 42px;
  height: 42px;
  display: grid;
  place-items: center;
  border-radius: 12px;
  background: rgba(69, 87, 163, 0.1);
  color: var(--auo-primary);
  font-size: 1.15rem;
}

.auo-page .auo__list-head h2 {
  margin: 0 0 0.25rem;
  font-size: 1rem;
  font-weight: 800;
}

.auo-page .auo__list-head p {
  margin: 0;
  font-size: 0.86rem;
  color: var(--auo-muted);
  line-height: 1.45;
}

.auo-page .auo-table-wrap {
  overflow-x: auto;
}

.auo-page .auo-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.88rem;
}

.auo-page .auo-table thead th {
  padding: 0.85rem 1rem;
  background: #f8fafc;
  color: #64748b;
  font-size: 0.68rem;
  font-weight: 800;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  text-align: left;
  border-bottom: 1px solid var(--auo-border);
  white-space: nowrap;
}

.auo-page .auo-table tbody td {
  padding: 0.85rem 1rem;
  border-bottom: 1px solid #f1f5f9;
  vertical-align: middle;
  color: #334155;
}

.auo-page .auo-table tbody tr:hover {
  background: #f8fafc;
}

.auo-page .auo-table__row--pending {
  background: #fffbeb;
}

.auo-page .auo-table__row--pending:hover {
  background: #fef3c7 !important;
}

.auo-page .auo-table__user strong {
  display: block;
  color: #1e293b;
  font-weight: 700;
}

.auo-page .auo-table__email {
  display: block;
  margin-top: 0.15rem;
  font-size: 0.78rem;
  color: #94a3b8;
}

.auo-page .auo-table__num {
  text-align: center;
}

.auo-page .auo-badge {
  display: inline-flex;
  align-items: center;
  padding: 0.15rem 0.5rem;
  border-radius: 999px;
  font-size: 0.75rem;
  font-weight: 700;
  white-space: nowrap;
}

.auo-page .auo-badge--today {
  background: #ecfdf5;
  color: #047857;
  border: 1px solid #a7f3d0;
}

.auo-page .auo-badge--never {
