  color: #b91c1c;
  border: 1px solid #fecaca;
}

.auo-page .auo-pill {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 1.75rem;
  padding: 0.12rem 0.45rem;
  border-radius: 999px;
  font-size: 0.78rem;
  font-weight: 800;
}

.auo-page .auo-pill--zero {
  background: #f1f5f9;
  color: #94a3b8;
}

.auo-page .auo-pill--msg {
  background: #eff6ff;
  color: #1d4ed8;
}

.auo-page .auo-pill--notif {
  background: #fff7ed;
  color: #c2410c;
}

.auo-page .auo-pill--total {
  background: #eef2ff;
  color: #4338ca;
}

.auo-page .auo-link {
  display: inline-flex;
  align-items: center;
  gap: 0.3rem;
  padding: 0.3rem 0.65rem;
  border-radius: 999px;
  background: #fff;
  border: 1px solid #c7d2fe;
  color: #4557a3;
  font-size: 0.78rem;
  font-weight: 700;
  text-decoration: none;
  white-space: nowrap;
}

.auo-page .auo-link:hover {
  background: #eef2ff;
  color: #3730a3;
}

.auo-page .auo-link--muted {
  border-color: #e2e8f0;
  color: #64748b;
}

.auo-page .auo-table__actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.4rem;
  justify-content: flex-end;
}

.auo-page .auo-empty {
  padding: 3rem 1.5rem;
  text-align: center;
  color: #94a3b8;
}

.auo-page .auo-empty i {
  display: block;
  font-size: 2rem;
  margin-bottom: 0.75rem;
}

.auo-page .auo__activity-card {
  margin-bottom: 1.25rem;
  background: var(--auo-surface);
  border: 1px solid var(--auo-border);
  border-radius: var(--auo-radius);
  box-shadow: var(--auo-shadow);
  overflow: hidden;
}

.auo-page .auo__card--page-visits {
  margin-bottom: 1.25rem;
}

.auo-page .auo-page-stats {
  display: grid;
  grid-template-columns: 1fr;
  gap: 0.85rem;
  padding: 0 1.25rem 1rem;
}

@media (min-width: 720px) {
  .auo-page .auo-page-stats {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}

.auo-page .auo-page-stats__item {
  padding: 0.95rem 1.05rem;
  border: 1px solid var(--auo-border);
  border-radius: 14px;
  background: #f8fafc;
}

.auo-page .auo-page-stats__item--top {
  border-color: #c7d2fe;
  background: #eef2ff;
}

.auo-page .auo-page-stats__label {
  display: block;
  margin-bottom: 0.25rem;
  color: var(--auo-muted);
  font-size: 0.68rem;
  font-weight: 800;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.auo-page .auo-page-stats__value {
  display: block;
  overflow: hidden;
  color: #1e293b;
  font-size: 1.05rem;
  font-weight: 800;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.auo-page .auo-page-stats__meta {
  display: block;
  margin-top: 0.2rem;
  color: #4557a3;
  font-size: 0.78rem;
  font-weight: 700;
}

.auo-page .auo-page-visits-wrap {
  overflow-x: auto;
  padding: 0 0 0.35rem;
}

.auo-page .auo-page-visits {
  width: 100%;
  border-collapse: collapse;
}

.auo-page .auo-page-visits th,
.auo-page .auo-page-visits td {
  padding: 0.85rem 1.1rem;
  border-top: 1px solid var(--auo-border);
  text-align: left;
  vertical-align: middle;
  font-size: 0.82rem;
}

.auo-page .auo-page-visits th {
  color: var(--auo-muted);
  font-size: 0.68rem;
  font-weight: 800;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  background: #f8fafc;
  border-top: 0;
}

.auo-page .auo-page-visits__rank {
  width: 2.5rem;
  color: var(--auo-muted);
  font-weight: 800;
}

.auo-page .auo-page-visits__page {
  min-width: 180px;
}

.auo-page .auo-page-visits__page strong,
.auo-page .auo-page-visits__page span {
  display: block;
}

.auo-page .auo-page-visits__page strong {
  color: #1e293b;
  font-size: 0.86rem;
}

.auo-page .auo-page-visits__page span {
  margin-top: 0.12rem;
  color: #94a3b8;
  font-size: 0.74rem;
  word-break: break-all;
}

.auo-page .auo-page-visits__row--top {
  background: #f8fafc;
}

.auo-page .auo-page-visits__bar-cell {
  min-width: 120px;
}

.auo-page .auo-page-visits__bar-track {
  height: 8px;
  overflow: hidden;
  border-radius: 999px;
  background: #e2e8f0;
}

.auo-page .auo-page-visits__bar {
  height: 100%;
  border-radius: 999px;
  background: linear-gradient(90deg, #4557a3 0%, #7c8ce8 100%);
}

@media (max-width: 720px) {
  .auo-page .auo-page-visits thead {
    display: none;
  }

  .auo-page .auo-page-visits tr {
    display: block;
    margin: 0.75rem 1rem;
    border: 1px solid var(--auo-border);
    border-radius: 12px;
    overflow: hidden;
  }

  .auo-page .auo-page-visits td {
    display: flex;
    justify-content: space-between;
    gap: 0.75rem;
    border-top: 0;
    border-bottom: 1px dashed var(--auo-border);
  }

  .auo-page .auo-page-visits td:last-child {
    border-bottom: 0;
  }

  .auo-page .auo-page-visits td::before {
    content: attr(data-label);
    flex: 0 0 auto;
    color: var(--auo-muted);
    font-size: 0.68rem;
    font-weight: 800;
    letter-spacing: 0.04em;
    text-transform: uppercase;
  }

  .auo-page .auo-page-visits__bar-cell {
    flex-direction: column;
    align-items: stretch;
  }
}

.auo-page .auo-activity__highlights {
  display: grid;
  grid-template-columns: 1fr;
  gap: 0.85rem;
  padding: 0 1.25rem 1rem;
}

@media (min-width: 640px) {
  .auo-page .auo-activity__highlights {
    grid-template-columns: 1fr 1fr;
  }
}

.auo-page .auo-activity__highlight {
  padding: 1rem 1.1rem;
  border-radius: 14px;
  border: 1px solid var(--auo-border);
}

.auo-page .auo-activity__highlight--peak {
  background: linear-gradient(135deg, #fff7ed 0%, #ffedd5 100%);
  border-color: #fed7aa;
}

.auo-page .auo-activity__highlight--quiet {
  background: linear-gradient(135deg, #f0fdf4 0%, #dcfce7 100%);
  border-color: #bbf7d0;
}

.auo-page .auo-activity__highlight-label {
  display: block;
  font-size: 0.72rem;
  font-weight: 800;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: #64748b;
  margin-bottom: 0.35rem;
}

.auo-page .auo-activity__highlight-value {
  display: block;
  font-size: 1.35rem;
  font-weight: 800;
  color: #1e293b;
  margin-bottom: 0.2rem;
}

.auo-page .auo-activity__highlight-meta {
  font-size: 0.82rem;
  color: #64748b;
  font-weight: 600;
}

.auo-page .auo-activity__chart {
  display: grid;
  grid-template-columns: repeat(24, minmax(0, 1fr));
  gap: 0.25rem;
  align-items: end;
  height: 180px;
  padding: 0 1.25rem 0.5rem;
  margin-bottom: 0.5rem;
}

.auo-page .auo-activity__bar-wrap {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: flex-end;
  height: 100%;
  min-width: 0;
}

.auo-page .auo-activity__bar {
  width: 100%;
  max-width: 18px;
  min-height: 4px;
  border-radius: 6px 6px 2px 2px;
  background: linear-gradient(180deg, #7c8ce8 0%, #5b6fd6 100%);
  transition: height 0.2s ease;
}

.auo-page .auo-activity__bar--peak {
  background: linear-gradient(180deg, #fb923c 0%, #ea580c 100%);
}

.auo-page .auo-activity__bar--quiet {
  background: linear-gradient(180deg, #86efac 0%, #22c55e 100%);
